using System;
using System.Collections.Generic;
using System.Linq;
namespace DeckRogue.GodotPort.Presentation;
// Pure shooter frame selector. Only the existing accepted projectile-release callback starts recoil.
// Target contact cannot restart this clock. No gameplay state, scheduling, wait or fence is owned here.
public sealed class CrossbowAuthoredFrames
{
 private readonly IReadOnlyDictionary<string,float[]> _clips;private readonly string _profile,_prepare;private readonly HashSet<string> _allowedMoves;
 public readonly record struct ReactionToken(long InstanceId,long Epoch,int OwnerVersion){public bool IsValid=>InstanceId>0&&Epoch>0&&OwnerVersion>=0;}
 private string PrepareClip=>_profile=="enemy_winch_warden"?"beamprepare":_profile=="enemy_seal_orb"?"beamprepare":_profile=="enemy_kin_priest"?(_move=="blood_beam"?"bloodprepare":"beamprepare"):_profile=="enemy_crab_cannon"?(_move=="laser"?"laserprepare":"precisionprepare"):_profile=="enemy_kin_follower"?"boomerangprepare":_profile=="enemy_thunder_globe"?(_move=="thunder_strike"?"thunderprepare":"burstprepare"):_profile=="enemy_elite_sentry"?(_move=="beam"?"beamprepare":"boltprepare"):_profile=="enemy_bomber"?(_move=="big_boom"?"boomprepare":"emberprepare"):_profile=="enemy_mud_lump"&&_move=="mud_toss"?"tossprepare":_prepare;
 private string ReleaseClip=>_profile=="enemy_winch_warden"?"beamrelease":_profile=="enemy_seal_orb"?"beamrelease":_profile=="enemy_kin_priest"?(_move=="blood_beam"?"bloodrelease":"beamrelease"):_profile=="enemy_crab_cannon"?(_move=="laser"?"laserrelease":"precisionrelease"):_profile=="enemy_kin_follower"?"boomerangrelease":_profile=="enemy_thunder_globe"?(_move=="thunder_strike"?"thunderrelease":"burstrelease"):_profile=="enemy_elite_sentry"?(_move=="beam"?"beamrelease":"boltrelease"):_profile=="enemy_bomber"?(_move=="big_boom"?"boomrelease":"emberrelease"):_profile=="enemy_cinder_imp"?"sparkrelease":_profile=="enemy_slug"?"spitrelease":_profile=="enemy_iron_clam"?"jetrelease":_profile=="enemy_mud_lump"?(_move=="mud_toss"?"tossrelease":"sloprelease"):_profile=="enemy_sludge_spider"?"oilrelease":"release";
 private readonly bool _ownedReactions;private static long _nextReactionInstance;private readonly long _reactionInstance=System.Threading.Interlocked.Increment(ref _nextReactionInstance);
 private long _reactionEpoch,_supportInstance=-1,_supportVersion=-1;private int _registeredOwner=-1,_supportExecution=-1;private float _epochStarted=-1;
 public ReactionToken CaptureReactionToken()=>_ownedReactions&&!_cancelled&&_registeredOwner>=0?new(_reactionInstance,_reactionEpoch,_registeredOwner):default;
 private void RegisterReactionOwner(float now,int owner){_supportInstance=_supportVersion=-1;_supportExecution=-1;_reactionEpoch++;_registeredOwner=owner;_epochStarted=now;_reaction="";_reactionAt=-1;_reactionOwner=-1;_released=-1;}
 private bool OwnsSupport(Style04EnemySupportMotion.Snapshot s)=>s.ProfileId==_profile&&s.Kind=="defend"&&s.MoveId=="guard"&&s.OwnerVersion==_registeredOwner&&s.InstanceId==_supportInstance&&s.Version==_supportVersion&&s.ExecutionIndex==_supportExecution;
 private bool _cancelled;private float _started=-1,_released=-1;private int _owner=-1,_version=-1,_execution=-1;
 private string _move="",_reaction="";private float _reactionAt=-1;private int _reactionOwner=-1;
 public float AcceptedReleaseAt=>_released;
 public BruteAuthoredFrames.Snapshot State{get;private set;}=BruteAuthoredFrames.Snapshot.Disabled;
 public CrossbowAuthoredFrames(IReadOnlyDictionary<string,float[]> clips,string profile="enemy_crossbow_archer"){_profile=profile;_ownedReactions=profile is "enemy_winch_warden" or "enemy_seal_orb" or "enemy_kin_priest" or "enemy_crab_cannon" or "enemy_kin_follower" or "enemy_thunder_globe" or "enemy_crossbow_archer" or "enemy_elite_sentry";_prepare=profile=="enemy_winch_warden"?"beamprepare":profile=="enemy_seal_orb"?"beamprepare":profile=="enemy_kin_priest"?"beamprepare":profile=="enemy_crab_cannon"?"precisionprepare":profile=="enemy_kin_follower"?"boomerangprepare":profile=="enemy_thunder_globe"?"thunderprepare":profile=="enemy_elite_sentry"?"boltprepare":profile=="enemy_bomber"?"emberprepare":profile=="enemy_cinder_imp"?"sparkprepare":profile=="enemy_slug"?"spitprepare":profile=="enemy_iron_clam"?"jetprepare":profile=="enemy_mud_lump"?"slopprepare":profile=="enemy_sludge_spider"?"oilprepare":profile=="enemy_crossbow_archer"?"windup":profile=="enemy_lost_soul"?"beamprepare":"prepare";_allowedMoves=profile switch{"enemy_winch_warden"=>new(){"hyper_beam"},"enemy_seal_orb"=>new(){"beam"},"enemy_kin_priest"=>new(){"beam","blood_beam"},"enemy_crab_cannon"=>new(){"precision_beam","laser"},"enemy_kin_follower"=>new(){"boomerang"},"enemy_thunder_globe"=>new(){"thunder_strike","galvanic_burst"},"enemy_elite_sentry"=>new(){"bolt","beam"},"enemy_bomber"=>new(){"toss_ember","big_boom"},"enemy_cinder_imp"=>new(){"spark_toss"},"enemy_slug"=>new(){"acid_spit"},"enemy_iron_clam"=>new(){"jet"},"enemy_mud_lump"=>new(){"slop","mud_toss"},"enemy_sludge_spider"=>new(){"oil_spray"},"enemy_lost_soul"=>new(){"eye_lasers"},"enemy_crossbow_archer"=>new(){"bolt","aimed_shot"},"enemy_spore_cap"=>new(){"frail_spores"},"enemy_hexer"=>new(){"mud"},_=>throw new ArgumentException("Unregistered release-authored profile")};var required=profile=="enemy_winch_warden"?new[]{"rest","beamprepare","beamrelease","recovery"}:profile=="enemy_seal_orb"?new[]{"rest","beamprepare","beamrelease","recovery"}:profile=="enemy_kin_priest"?new[]{"rest","beamprepare","beamrelease","beamrebound","bloodprepare","bloodrelease","bloodrebound","recovery"}:profile=="enemy_crab_cannon"?new[]{"rest","precisionprepare","precisionrelease","laserprepare","laserrelease","recovery"}:profile=="enemy_kin_follower"?new[]{"rest","boomerangprepare","boomerangrelease","recovery"}:profile=="enemy_thunder_globe"?new[]{"rest","thunderprepare","thunderrelease","burstprepare","burstrelease","recovery"}:profile=="enemy_elite_sentry"?new[]{"rest","boltprepare","boltrelease","beamprepare","beamrelease","recovery"}:profile=="enemy_bomber"?new[]{"rest","emberprepare","emberrelease","boomprepare","boomrelease","recovery"}:profile=="enemy_cinder_imp"?new[]{"rest","sparkprepare","sparkrelease","recovery"}:profile=="enemy_slug"?new[]{"rest","spitprepare","spitrelease","recovery"}:profile=="enemy_iron_clam"?new[]{"rest","jetprepare","jetrelease","recovery"}:profile=="enemy_mud_lump"?new[]{"rest","slopprepare","sloprelease","tossprepare","tossrelease","recovery"}:profile=="enemy_sludge_spider"?new[]{"rest","oilprepare","oilrelease","recovery"}:new[]{"rest",_prepare,"release","recovery"};if(!required.All(clips.ContainsKey)||clips.Any(p=>p.Value.Length==0||p.Value.Any(x=>!float.IsFinite(x)||x<=0)))throw new ArgumentException("Invalid crossbow clip durations");_clips=clips.ToDictionary(x=>x.Key,x=>(float[])x.Value.Clone());}
 public void Begin(){if(!_ownedReactions)_cancelled=false;}
 public void BeginSupport(float now,Style04EnemySupportMotion.Snapshot s){if(!_ownedReactions){Begin();return;}if(!float.IsFinite(now)||now<0||!s.Active||s.ProfileId!=_profile||s.Kind!="defend"||s.MoveId!="guard"||s.OwnerVersion<0)return;_cancelled=false;RegisterReactionOwner(now,s.OwnerVersion);_supportInstance=s.InstanceId;_supportVersion=s.Version;_supportExecution=s.ExecutionIndex;}
 public void BeginAttack(float now,Style04EnemyMotion.Snapshot a){if(!float.IsFinite(now)||now<0||!a.Active||a.ProfileId!=_profile||!_allowedMoves.Contains(a.MoveId)||(_ownedReactions&&a.OwnerVersion<0))return;_cancelled=false;if(_ownedReactions)RegisterReactionOwner(now,a.OwnerVersion);_started=now;_released=-1;_owner=a.OwnerVersion;_version=a.Version;_execution=a.ExecutionIndex;_move=a.MoveId;}
 private bool Owns(Style04EnemyMotion.Snapshot a)=>a.ProfileId==_profile&&a.OwnerVersion==_owner&&a.Version==_version&&a.ExecutionIndex==_execution&&a.MoveId==_move;
 public bool AcceptedRelease(Style04EnemyMotion.Snapshot a){if(_cancelled||!a.Active||!Owns(a)||_released>=0||a.AcceptedContacts!=0||!float.IsFinite(a.ReleaseAt)||a.ReleaseAt<_started)return false;_released=a.ReleaseAt;return true;}
 public void ResumeIdleForPlacement(float now=0,int owner=0){if(_ownedReactions){if(!float.IsFinite(now)||now<0||owner<0)return;RegisterReactionOwner(now,owner);}_cancelled=false;_reaction="";_reactionAt=-1;_reactionOwner=-1;}
 public void Cancel(){if(_ownedReactions){_reactionEpoch++;_registeredOwner=-1;_epochStarted=-1;}_cancelled=true;_started=_released=-1;_owner=_version=_execution=-1;_move=_reaction="";_reactionAt=-1;_reactionOwner=-1;}
 public void NotifyPose(string name,float now,int owner){if(_ownedReactions){NotifyPose(name,now,owner,CaptureReactionToken());return;}if(name is not ("hurt" or "block")||!float.IsFinite(now)||now<0)return;_reaction=name;_reactionAt=now;_reactionOwner=owner;_cancelled=false;}
 public bool NotifyPose(string name,float now,int owner,ReactionToken token){if(!_ownedReactions||_cancelled||!token.IsValid||token.InstanceId!=_reactionInstance||token.Epoch!=_reactionEpoch||token.OwnerVersion!=_registeredOwner||owner!=_registeredOwner||name is not ("hurt" or "block")||!float.IsFinite(now)||now<_epochStarted||now<0)return false;_reaction=name;_reactionAt=now;_reactionOwner=owner;return true;}
 private float Duration(string clip,float fallback)=>_clips.TryGetValue(clip,out var a)?a.Sum():fallback;
 private BruteAuthoredFrames.Snapshot Pick(string requested,float age,bool loop,string reason,bool active,int owner,Style04EnemyMotion.Snapshot a){bool missing=!_clips.TryGetValue(requested,out var d);string clip=missing?"rest":requested;if(missing)d=_clips["rest"];float t=Math.Max(0,age),length=d!.Sum();if(loop)t%=length;int index=0;while(index<d.Length-1&&t>=d[index]){t-=d[index];index++;}return State=new(requested,clip,index,reason,missing,active,owner,a.Version,a.ExecutionIndex,a.AcceptedContacts,a.LastOrdinal,a.LastContactAt);}
 public BruteAuthoredFrames.Snapshot Sample(float now,Style04EnemyMotion.Snapshot a,Style04EnemySupportMotion.Snapshot support,int owner,bool dead){
  if(!float.IsFinite(now)||now<0)return Pick("rest",0,false,"invalid-clock",false,owner,a);
  if(dead)return Pick("rest",0,false,"dead",false,owner,a);
  if(_cancelled)return Pick("rest",0,false,"cancelled",false,owner,a);
  if(_ownedReactions&&owner!=_registeredOwner)return Pick("rest",0,false,"unregistered-owner",false,owner,a);
  float reactionAge=now-_reactionAt;
  if(_reaction=="hurt"&&_reactionOwner==owner&&reactionAge>=0&&reactionAge<Duration("hurt",.18f))return Pick("hurt",reactionAge,false,"hurt-notification",true,owner,a);
  if(a.Active&&a.OwnerVersion==owner){
   if(!Owns(a))return Pick("rest",0,false,"unowned-attack",false,owner,a);
   if(_released<0)return Pick(a.AcceptedContacts>0?"rest":PrepareClip,Math.Max(0,now-_started),false,a.AcceptedContacts>0?"missing-actual-release":"awaiting-real-release",true,owner,a);
   float age=now-_released;if(age<0)return Pick(PrepareClip,Math.Max(0,now-_started),false,"before-observed-release",true,owner,a);
   float hold=Duration(ReleaseClip,.10f);if(age<hold)return Pick(ReleaseClip,age,false,"accepted-real-release",true,owner,a);
   if(_profile=="enemy_kin_priest")return Pick(_move=="blood_beam"?"bloodrebound":"beamrebound",age-hold,false,"awaiting-first-real-contact",true,owner,a);
   if(age<hold+Duration("recovery",.20f))return Pick("recovery",age-hold,false,"release-recovery",true,owner,a);
   return Pick("rest",0,false,"post-release-ready",true,owner,a);
  }
  if(_reaction=="block"&&_reactionOwner==owner&&reactionAge>=0&&reactionAge<Duration("block",.18f))return Pick("block",reactionAge,false,"block-notification",true,owner,a);
  if(support.Active&&support.OwnerVersion==owner){
   if(!_ownedReactions)return Pick(support.Kind=="defend"?"block":"support",Math.Max(0,now-support.StartedAt),false,"support-action",true,owner,a);
   if(!OwnsSupport(support))return Pick("rest",0,false,"unowned-support",false,owner,a);
   bool pulse=support.AcceptedPulses>0&&support.LastPulseAt>=0;
   bool pulseHold=pulse&&now-support.LastPulseAt>=0&&now-support.LastPulseAt<.055f;
   if((support.Phase=="recovery"||support.Phase=="deadline-recovery")&&!pulseHold)return Pick("recovery",Math.Max(0,now-(support.EndRequestedAt>=0?support.EndRequestedAt:support.Deadline-.18f)),false,"support-recovery",true,owner,a);
   return Pick(pulse?"guardhold":"guardprepare",0,false,pulse?"accepted-real-block-gained":"awaiting-real-block-gained",true,owner,a);
  }
  return Pick("idle",now,true,"idle",false,owner,a);
 }
}
